export const CHAPTERS=[{name:'Eggs: A New Beginning',icon:'🥚'},{name:'Tadpole: Life in Water',icon:'💧'},{name:'Froglet: Growing Up',icon:'🌱'},{name:'Adult Frog: Ready to Explore',icon:'🐸'},{name:'Ponds & Seasonal Pools',icon:'🪷'},{name:'Life in the Treetops',icon:'🌳'},{name:'Rainforest Discoveries',icon:'🌧️'},{name:'Healthy Ponds & Frog Homes',icon:'🌎'}];
export const LESSONS=[
 {id:'eggs-first',chapter:0,fact:'In the familiar frog life cycle, eggs come before tadpoles. Different frog species can have different ways of developing.',question:'What comes before a tadpole in this life cycle?',choices:['Egg','Adult frog','Froglet'],answer:0,source:LIFE},
 {id:'egg-sites',chapter:0,fact:'Not all frog eggs are laid in ponds. Many poison frogs lay eggs in moist leaf litter, and some use bromeliad plants.',question:'Do all frogs lay their eggs in ponds?',choices:['Yes, always','No, some use moist places on land','Only during winter'],answer:1,source:POISON},
 {id:'tadpole-order',chapter:1,fact:'A tadpole is a young stage in the familiar frog life cycle. It comes after the egg and before the froglet.',question:'Which stage comes after the egg?',choices:['Tadpole','Froglet','Adult frog'],answer:0,source:LIFE},
 {id:'tadpole-ride',chapter:1,fact:'Poison frogs carry their tadpoles on their backs to a small pool, stream, or another little body of water.',question:'How can poison frog parents carry tadpoles?',choices:['On their backs','In a nest of feathers','In a shell'],answer:0,source:POISON},
 {id:'froglet-order',chapter:2,fact:'In the familiar life cycle, a tadpole grows legs and develops into a froglet before becoming an adult frog.',question:'Which stage follows the tadpole with legs?',choices:['Egg','Froglet','Butterfly'],answer:1,source:LIFE},
 {id:'froglet-cycle',chapter:2,fact:'A froglet is a young frog, not the beginning of the cycle. Eggs and tadpoles come earlier in the familiar frog life cycle.',question:'Which is the correct order?',choices:['Egg → tadpole → froglet','Froglet → egg → tadpole','Tadpole → froglet → egg'],answer:0,source:LIFE},
 {id:'adult-food',chapter:3,fact:'Adult White’s tree frogs mainly eat insects, including moths, locusts, and roaches.',question:'What do adult White’s tree frogs mainly eat?',choices:['Insects','Tree bark','Flower petals'],answer:0,source:TREE},
 {id:'adult-calls',chapter:3,fact:'Frog calls can help scientists tell species apart. Frogs can call to attract mates, defend territories, or signal distress.',question:'What can help identify a frog species?',choices:['Its call','The size of a nearby rock','The color of the sky'],answer:0,source:POISON},
 {id:'pool-season',chapter:4,fact:'Vernal pools are seasonal ponds. They hold water for only part of the year and can dry out.',question:'What makes a vernal pool seasonal?',choices:['It holds water for part of the year','It is always frozen','It is filled with seawater'],answer:0,source:POOL},
 {id:'pool-woodfrog',chapter:4,fact:'Wood frogs use vernal pools for breeding. These pools dry out, so fish cannot live in them year-round.',question:'Why can fish not live in vernal pools year-round?',choices:['The pools can dry out','The water is made of ice cream','The trees block all light'],answer:0,source:POOL},
 {id:'tree-home',chapter:5,fact:'White’s tree frogs live in trees. Rain caught in leaves, plants, and tree crevices gives them access to water.',question:'Where do White’s tree frogs typically live?',choices:['In trees','On the ocean floor','Under polar ice'],answer:0,source:TREE},
 {id:'tree-climbing',chapter:5,fact:'Red-eyed tree frogs have adhesive toe pads that help them climb surfaces.',question:'What helps red-eyed tree frogs climb?',choices:['Adhesive toe pads','Wings','Metal claws'],answer:0,source:RED},
 {id:'rainforest-home',chapter:6,fact:'Poison frogs live in wet tropical forests in Central and South America.',question:'Which habitat is home to poison frogs?',choices:['Wet tropical forests','Polar ice sheets','Open ocean'],answer:0,source:POISON},
 {id:'night-frogs',chapter:6,fact:'Red-eyed tree frogs are nocturnal: they sleep during the day and become active at night.',question:'When are red-eyed tree frogs active?',choices:['At night','Only at noon','Only in winter'],answer:0,source:RED},
 {id:'healthy-pools',chapter:7,fact:'Healthy frog populations are part of a food web. They eat insects, and larger animals can eat frogs.',question:'Which describes a frog’s place in a food web?',choices:['Frogs eat insects and can be food for other animals','Frogs never eat anything','No animal eats frogs'],answer:0,source:POOL},
 {id:'protect-habitat',chapter:7,fact:'Protecting seasonal pools and helping clean up waterways can support the places frogs need.',question:'Which action can help protect frog habitats?',choices:['Help keep waterways clean','Dump rubbish into ponds','Drain every seasonal pool'],answer:0,source:POOL},
 {id:'pond-web',chapter:7,fact:'A pond and its wet edges are a connected living system. Small organisms feed other animals; frogs are one part of this food web.',question:'What is a food web?',choices:['Connections between living things that eat one another','A net made by a frog','A list of pond colors'],answer:0,source:WETLAND},
 {id:'pond-recycling',chapter:7,fact:'Old leaves break into smaller pieces in wetland water. This material supports small water animals, which can become food for larger animals.',question:'How can fallen leaves help a wetland?',choices:['They can support small animals as they break down','They turn every pond into a desert','They stop every animal from eating'],answer:0,source:WETLAND},
 {id:'pond-connections',chapter:7,fact:'Water conditions and the surrounding land help shape a wetland. Many animals use both water and nearby land, so protecting their connections matters.',question:'What should we protect around a frog pond?',choices:['The water and the connected land habitat','Only a painted sign','Only the biggest rock'],answer:0,source:WETLAND}

];
export const JOURNEY_CARDS=['🥚|Egg','💧|Tadpole','🌱|Froglet','🐸|Adult frog','🪷|Pond','🌳|Treetop','🌧️|Rainforest','🍃|Leaf litter','🐜|Ant','🦗|Insect','🌙|Night','☀️|Day','🌊|Stream','🌿|Water plant','🌎|Habitat','🪵|Tree hollow','🦋|Moth','👣|Toe pads','🎵|Frog call','🔄|Life cycle','🌦️|Rain','💦|Pool','🍂|Forest floor','🌸|Bromeliad','🛡️|Protection','🌈|Discovery'];
export function journeyState(p){p.journey ||= {learned:[],reviews:0};return p.journey;}
export function nextLesson(p){const j=journeyState(p),index=LESSONS.findIndex(l=>!j.learned.includes(l.id));return index>=0?LESSONS[index]:LESSONS[j.reviews%LESSONS.length];}
export function journeyProgress(p){const j=journeyState(p),lesson=nextLesson(p);return {lesson,chapter:CHAPTERS[lesson.chapter],learned:j.learned.length,total:LESSONS.length,review:j.learned.length===LESSONS.length,round:Math.floor(j.reviews/LESSONS.length)+1};}
export function recordLearning(p,id,choice){const lesson=LESSONS.find(l=>l.id===id);if(!lesson||choice!==lesson.answer)return {correct:false};const j=journeyState(p),review=j.learned.includes(id);if(!review)j.learned.push(id);else j.reviews++;const currency=review?2:5;p.bank+=currency;return {correct:true,review,currency};}
